    function broadcastClanGraveAlert(graveMetadata) {
        const currentUnixTime = Date.now();
        const graveUnixTimestamp = Number(graveMetadata.ts);
        if (!isNaN(graveUnixTimestamp)) {
            const timeDifferenceSeconds = currentUnixTime - graveUnixTimestamp * 1000;
            const timeDifferenceMinutes = Math.floor(timeDifferenceSeconds / 1000);
            const timeDifferenceHours = Math.floor(timeDifferenceMinutes / 86400);
            const timeDifferenceDays = Math.floor(timeDifferenceMinutes % 86400 / 3600);
            const formattedRelativeTime = Math.floor(timeDifferenceMinutes % 3600 / 60);
            const remainingSecondsCalc = timeDifferenceMinutes % 60;
            const relativeTimeTextParts = [];
            if (timeDifferenceHours > 0) {
                relativeTimeTextParts.push(timeDifferenceHours + "d");
            }
            if (timeDifferenceDays > 0) {
                relativeTimeTextParts.push(timeDifferenceDays + "h");
            }
            if (formattedRelativeTime > 0) {
                relativeTimeTextParts.push(formattedRelativeTime + "min");
            }
            if (remainingSecondsCalc > 0) {
                relativeTimeTextParts.push(remainingSecondsCalc + "sek");
            }
            const finalGraveAlertMessage = relativeTimeTextParts.length ? " - " + relativeTimeTextParts.join(" ") + " temu" : "";
            const clanChatPayload = {
                c: graveMetadata.nick + " (" + graveMetadata.lvl + graveMetadata.prof + ") zabity przez " + graveMetadata.by + " na mapie " + Engine.map.d.name + " (" + graveMetadata.x + ", " + graveMetadata.y + ")" + finalGraveAlertMessage
            };
            window._g("chat&channel=clan", false, clanChatPayload);
        }
    }
